(2, 'Administrator', 'admin', 'General administrative access with limited system configuration capabilities', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(3, 'Chief', 'chief', 'Kitchen operations: recipes, inventory viewing, menu planning', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(4, 'Service Manager', 'service-manager', 'Customer-facing operations: orders, reservations, customer management', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(5, 'Finance Manager', 'finance-manager', 'Financial operations: payments, invoices, expenses, financial reports', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(6, 'HR Manager', 'hr-manager', 'Human resources: employee management, payroll, attendance, shifts', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(7, 'Inventory Manager', 'inventory-manager', 'Full inventory control: stock management, suppliers, purchase orders', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(8, 'Operations Manager', 'operations-manager', 'Operational setup: locations, tables, floors, operating hours', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(9, 'Viewer', 'viewer', 'Read-only access to reports, orders, and inventory for auditing purposes', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(10, 'Manager', 'manager', 'Legacy manager role (deprecated - use specific manager roles)', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
(11, 'Employee', 'employee', 'General employee access', '2025-12-19 08:34:59', '2025-12-19 08:34:59'),
